"""Hidden behavioral tests for jo: fuzz. Generated by pbkit from the gold binary."""


def test_fuzz_000(run):
    r = run(args=['-B', '--', '-s', '1', 'p.q.r@[', '-s', '@1', '', '-b', '1e3'], files={'f.txt': b'file text\n', 'j.json': b'{"j":[1,null]}'})
    assert r.stdout == b'{"p.q.r":false,"":true}\n'
    assert r.stderr == b"Argument `1' is neither k=v nor k@v\nArgument `' is neither k=v nor k@v\nArgument `1e3' is neither k=v nor k@v\n"
    assert r.returncode == 0


def test_fuzz_001(run):
    r = run(args=['-a', 'name@[', '0', 'a[b]=1e3'], files={'f.txt': b'file text\n', 'j.json': b'{"j":[1,null]}'})
    assert r.stdout == b'["name@[",0,"a[b]=1e3"]\n'
    assert r.stderr == b''
    assert r.returncode == 0


